// 수집할 뉴스 소스 목록.
// 항목을 추가/삭제하면 클리핑 대상이 바뀝니다.
const 소스 = [
  { 카테고리: '주요뉴스', url: 'https://news.google.com/rss?hl=ko&gl=KR&ceid=KR:ko' },
  { 카테고리: '경제',     url: 'https://news.google.com/rss/headlines/section/topic/BUSINESS?hl=ko&gl=KR&ceid=KR:ko' },
  { 카테고리: 'IT·기술',  url: 'https://news.google.com/rss/headlines/section/topic/TECHNOLOGY?hl=ko&gl=KR&ceid=KR:ko' },
  { 카테고리: 'AI',       url: 'https://news.google.com/rss/search?q=' + encodeURIComponent('AI 인공지능') + '&hl=ko&gl=KR&ceid=KR:ko' },
];

const 설정 = $('설정').first().json;

return 소스.map((s) => ({
  json: {
    카테고리: s.카테고리,
    url: s.url,
    받는사람: 설정.받는사람,
    보내는사람: 설정.보내는사람,
    수집시간_시간: 설정.수집시간_시간,
    카테고리당_최대건수: 설정.카테고리당_최대건수,
  },
}));

// RSS 원본 → 카테고리별 정리 (최근 N시간 / 중복 제거 / 최신순 / 건수 제한)
const 설정 = $('설정').first().json;
const 시간제한 = Number(설정.수집시간_시간) || 24;
const 최대건수 = Number(설정.카테고리당_최대건수) || 8;
const 기준시각 = Date.now() - 시간제한 * 60 * 60 * 1000;

const 정규화 = (s) =>
  String(s || '')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();

const 입력 = $input.all();
const 기사목록 = [];

for (let i = 0; i < 입력.length; i++) {
  const j = 입력[i].json;
  if (!j || (!j.title && !j.link)) continue;

  // 이 기사가 어느 소스(카테고리)에서 왔는지 역추적
  let 카테고리 = '기타';
  try {
    카테고리 = $('뉴스 소스 목록').itemMatching(i)?.json?.카테고리 || '기타';
  } catch (e) {
    카테고리 = '기타';
  }

  const 발행 = j.isoDate || j.pubDate || j.date;
  const 발행시각 = 발행 ? new Date(발행).getTime() : NaN;

  // 발행일이 없는 기사는 버리지 않고 통과 (일부 피드는 날짜를 주지 않음)
  if (!Number.isNaN(발행시각) && 발행시각 < 기준시각) continue;

  const 제목 = 정규화(j.title);
  if (!제목) continue;

  // 구글뉴스 제목의 " - 언론사" 꼬리에서 출처 분리
  const m = 제목.match(/^(.*\S)\s+-\s+([^-]{1,30})$/);

  기사목록.push({
    카테고리,
    제목: m ? m[1].trim() : 제목,
    출처: m ? m[2].trim() : 정규화(j.creator || j.author),
    링크: j.link || '',
    요약: 정규화(j.contentSnippet || j.content || '').slice(0, 180),
    발행시각: Number.isNaN(발행시각) ? Date.now() : 발행시각,
  });
}

// 중복 제거 (링크 우선, 없으면 제목)
const 본것 = new Set();
const 유일 = [];
for (const a of 기사목록) {
  const 키 = (a.링크 || a.제목).split('?')[0];
  if (본것.has(키)) continue;
  본것.add(키);
  유일.push(a);
}

// 카테고리별 그룹 → 최신순 → 건수 제한
const 순서 = ['주요뉴스', '경제', 'IT·기술', 'AI', '기타'];
const 그룹 = {};
for (const a of 유일) (그룹[a.카테고리] ||= []).push(a);

const 결과 = [];
for (const c of 순서) {
  if (!그룹[c]?.length) continue;
  그룹[c].sort((x, y) => y.발행시각 - x.발행시각);
  결과.push({ 카테고리: c, 기사: 그룹[c].slice(0, 최대건수) });
}

return [
  {
    json: {
      총건수: 결과.reduce((n, g) => n + g.기사.length, 0),
      카테고리수: 결과.length,
      그룹: 결과,
      받는사람: 설정.받는사람,
      보내는사람: 설정.보내는사람,
      수집시간_시간: 시간제한,
    },
  },
];

// 메일 본문(HTML + 텍스트) 생성
const d = $input.first().json;

const 날짜 = new Intl.DateTimeFormat('ko-KR', {
  timeZone: 'Asia/Seoul',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  weekday: 'long',
}).format(new Date());

const esc = (s) =>
  String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const 시각 = (ts) =>
  new Intl.DateTimeFormat('ko-KR', {
    timeZone: 'Asia/Seoul',
    hour: '2-digit',
    minute: '2-digit',
  }).format(new Date(ts));

const 색 = {
  '주요뉴스': '#2563eb',
  '경제': '#059669',
  'IT·기술': '#7c3aed',
  'AI': '#db2777',
  '기타': '#64748b',
};

let 본문 = '';
let 텍스트 = `${날짜} 뉴스 클리핑\n최근 ${d.수집시간_시간}시간 · 총 ${d.총건수}건\n\n`;

for (const g of d.그룹) {
  const c = 색[g.카테고리] || '#64748b';
  본문 += `<tr><td style="padding:28px 24px 10px">
    <span style="display:inline-block;background:${c};color:#fff;font-size:12px;font-weight:700;padding:5px 12px;border-radius:20px;letter-spacing:.3px">${esc(g.카테고리)}</span>
    <span style="color:#94a3b8;font-size:12px;margin-left:8px">${g.기사.length}건</span>
  </td></tr>`;

  텍스트 += `\n[${g.카테고리}]\n`;

  for (const a of g.기사) {
    const 메타 = [a.출처, 시각(a.발행시각)].filter(Boolean).join(' · ');
    본문 += `<tr><td style="padding:0 24px 14px">
      <div style="border-left:3px solid ${c};padding-left:14px">
        <a href="${esc(a.링크)}" style="color:#0f172a;font-size:15px;font-weight:600;text-decoration:none;line-height:1.45">${esc(a.제목)}</a>
        <div style="color:#94a3b8;font-size:12px;margin-top:5px">${esc(메타)}</div>
        ${a.요약 ? `<div style="color:#475569;font-size:13px;line-height:1.6;margin-top:6px">${esc(a.요약)}</div>` : ''}
      </div>
    </td></tr>`;

    텍스트 += `- ${a.제목}${메타 ? ` (${메타})` : ''}\n  ${a.링크}\n`;
  }
}

const html = `<!doctype html>
<html lang="ko"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#f1f5f9">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:24px 12px">
<tr><td align="center">
<table role="presentation" width="620" cellpadding="0" cellspacing="0" style="max-width:620px;width:100%;background:#fff;border-radius:14px;overflow:hidden;font-family:-apple-system,BlinkMacSystemFont,'Malgun Gothic','맑은 고딕',sans-serif">
  <tr><td style="background:#0f172a;padding:26px 24px">
    <div style="color:#fff;font-size:20px;font-weight:700">오늘의 뉴스 클리핑</div>
    <div style="color:#94a3b8;font-size:13px;margin-top:6px">${esc(날짜)} · 최근 ${d.수집시간_시간}시간 · 총 ${d.총건수}건</div>
  </td></tr>
  ${본문}
  <tr><td style="padding:20px 24px 26px;border-top:1px solid #e2e8f0">
    <div style="color:#94a3b8;font-size:11px;line-height:1.6">n8n 자동 발송 · 매일 오전 7시</div>
  </td></tr>
</table>
</td></tr></table>
</body></html>`;

return [
  {
    json: {
      제목: `[뉴스 클리핑] ${날짜} · ${d.총건수}건`,
      html,
      텍스트,
      받는사람: d.받는사람,
      보내는사람: d.보내는사람,
      총건수: d.총건수,
    },
  },
];
